const d=$json??{};const e=d.enquiry??{};const aps=Array.isArray(d.appointments)?d.appointments:[];const ap=aps.find(x=>['confirmed','held'].includes(x.status))||aps[0]||{};
const esc=(v)=>String(v??'').replace(/[&<>\"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
const pretty=(iso)=>iso?new Date(iso+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'';
const b=String(e.booking_status??''), s=String(e.status??''), a=String(ap.status??'');
const date=ap.appointment_date||e.preferred_date||'';const time=String(ap.start_time||e.preferred_time_window||'').slice(0,5);
let label='Pending confirmation', detail='Your appointment request is waiting for a Favfare team member to confirm it.', cls='pending';
if(b==='confirmed'||s==='booked'||a==='confirmed'){label='Confirmed';detail='Your appointment has been confirmed by the Favfare team.';cls='confirmed';}
else if(b==='proposed'){label='New time proposed';detail='The Favfare team proposed another appointment time. Contact the team if you need to adjust it.';cls='proposed';}
else if(s==='closed'){label='Closed';detail='This enquiry has been closed by the Favfare team.';cls='closed';}
const service=e.service?.name||'Favfare appointment';const patient=e.contact?.full_name||'Patient';
const html='<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Favfare Booking Status</title><style>body{margin:0;font-family:Inter,system-ui;background:#e7eee9;color:#17241e;min-height:100vh;display:grid;place-items:center;padding:24px}.card{width:min(520px,100%);background:#fff;border-radius:24px;padding:28px;box-shadow:0 24px 70px rgba(16,50,36,.18)}.brand{font-size:12px;font-weight:850;letter-spacing:.14em;color:#426454}.state{margin:22px 0;padding:18px;border-radius:16px;border:1px solid #d7dfda}.state.confirmed{background:#f2fff8;border-color:#7fc5a5}.state.pending{background:#fffbed;border-color:#e0c66f}.state.proposed{background:#f4f9ff;border-color:#9ab8d6}.state.closed{background:#f7f7f7}.state strong{font-size:24px}.state p{color:#65716b;line-height:1.55}.row{padding:10px 0;border-bottom:1px solid #eef1ef}.row:last-child{border:0}.row span{display:block;font-size:11px;color:#7a8580}.row b{font-size:14px}.actions{display:grid;gap:8px;margin-top:20px}.actions a{text-align:center;text-decoration:none;background:#075e54;color:#fff;padding:12px;border-radius:12px;font-weight:800}.actions a.secondary{background:#fff;color:#075e54;border:1px solid #a9c7b8}</style></head><body><main class=\"card\"><div class=\"brand\">FAVFARE · PATIENT STATUS</div><div class=\"state '+cls+'\"><strong>'+esc(label)+'</strong><p>'+esc(detail)+'</p></div><div class=\"row\"><span>Patient</span><b>'+esc(patient)+'</b></div><div class=\"row\"><span>Service</span><b>'+esc(service)+'</b></div><div class=\"row\"><span>Appointment</span><b>'+esc(pretty(date))+(time?' · '+esc(time):'')+'</b></div><div class=\"actions\"><a href=\"/webhook/favfare-demo/patient-status?enquiry_id='+encodeURIComponent(e.id||'')+'\">Refresh status</a><a class=\"secondary\" href=\"/webhook/favfare-demo/crm-ui\" target=\"_blank\">Open staff CRM</a></div></main></body></html>';
return[{json:{html}}];
